#include "DSP/PlateEngine.h"
#include "Presets/FactoryPresets.h"
#include <iostream>
int main(){std::cout<<"number,name,input_peak,output_peak,output_peak_dbfs\n";for(int n=0;n<platebank::count;++n){auto&v=platebank::presets[n].values;plate::Parameters p;p.plate=int(v[0]);for(int i=0;i<3;++i)p.rt[i]=v[i+1];p.filterModel=int(v[4]);p.emt=int(v[5]);p.martech=int(v[6]);p.width=v[7];p.balance=v[8];p.eq=v[9]>.5;p.lowFreq=v[10];p.lowGain=v[11];p.highFreq=v[12];p.highGain=v[13];p.rate=v[14];p.depth=v[15];p.predelay=v[16];p.mix=v[17];p.wetSolo=v[18]>.5;p.power=true;plate::Engine e;e.prepare(48000);double inputPeak=0,peak=0;for(int i=0;i<48000*4;++i){const double x=.04*(std::sin(2*plate::pi*80*i/48000)+std::sin(2*plate::pi*997*i/48000)+std::sin(2*plate::pi*8003*i/48000));auto y=e.tick(x,x,p);inputPeak=std::max(inputPeak,std::abs(x));if(i>48000*2)peak=std::max(peak,std::max(std::abs(y[0]),std::abs(y[1])));}std::cout<<n+1<<','<<platebank::presets[n].name<<','<<inputPeak<<','<<peak<<','<<20*std::log10(peak)<<'\n';}}
